/* Signature Greek Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Nikomedes": "From nike (victory) + medos (counsel).", "Marianna": "From Maria + Anna.", "Georgionike": "From Georgios + nike (victory).", "Elenipetra": "From Eleni + petra (rock).", "Dimitrokles": "From Dimitrios + kleos (glory).", "Kateriniki": "From Katerina + nike.", "Nikomedopoulos": "Signature surname in -opoulos style.", "Georgionikidis": "Signature surname in -idis style.", "Elenipetrou": "Signature surname in genitive style.", "Dimitroklidis": "Signature surname in -idis style."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Nikomedes';
console.log(lookup(q));

